35	export class XAIImageProvider extends OpenAiImageProvider {
36	  config: XaiImageOptions;
37	
38	  constructor(
39	    modelName: string,
40	    options: { config?: XaiImageOptions; id?: string; env?: EnvOverrides } = {},
41	  ) {
42	    const userConfig = options.config || {};
43	    // Resolve the base URL up front so `region` actually takes effect: the OpenAI
44	    // base provider reads `config.apiBaseUrl` directly and never calls our
45	    // `getApiUrlDefault()` when it's set, so an unconditional default would
46	    // silently swallow a regional override.
47	    const apiBaseUrl =
48	      userConfig.apiBaseUrl ??
49	      (userConfig.region ? `https://${userConfig.region}.api.x.ai/v1` : 'https://api.x.ai/v1');
50	
51	    super(modelName, {
52	      ...options,
53	      config: {
54	        ...userConfig,
55	        apiKeyEnvar: 'XAI_API_KEY',
56	        apiBaseUrl,
57	      },
58	    });
59	    this.config = userConfig;
60	  }
61	
62	  getApiKey(): string | undefined {
63	    if (this.config?.apiKey) {
64	      return this.config.apiKey;
65	    }
66	    return getEnvString('XAI_API_KEY');
67	  }
68	
69	  getApiUrlDefault(): string {
70	    if (this.config.region) {
71	      return `https://${this.config.region}.api.x.ai/v1`;
72	    }
73	    return 'https://api.x.ai/v1';
74	  }
75	
76	  id(): string {
77	    return `xai:image:${this.modelName}`;
78	  }
79	
80	  toString(): string {
81	    return `[xAI Image Provider ${this.modelName}]`;
82	  }
83	
84	  private getApiModelName(): string {
85	    const modelMap: Record<string, string> = {
86	      'grok-imagine-image': 'grok-imagine-image',
87	      // Dated alias for grok-imagine-image, as listed by xAI's image-generation-models API.
88	      'grok-imagine-image-2026-03-02': 'grok-imagine-image',
89	      'grok-imagine-image-pro': 'grok-imagine-image-pro',
90	      'grok-2-image': 'grok-2-image',
91	      'grok-image': 'grok-2-image',
92	    };
93	    return modelMap[this.modelName] || 'grok-2-image';
94	  }
95	
96	  private calculateImageCost(model: string, n: number = 1): number {
97	    if (model === 'grok-imagine-image') {
98	      return 0.02 * n;
99	    }
100	    if (model === 'grok-imagine-image-pro') {
101	      return 0.07 * n;
102	    }
103	
104	    // Legacy grok-2-image pricing.
105	    return 0.07 * n;
106	  }
