108	  async callApi(
109	    prompt: string,
110	    context?: CallApiContextParams,
111	    _callApiOptions?: CallApiOptionsParams,
112	  ): Promise<ProviderResponse> {
113	    if (this.requiresApiKey() && !this.getApiKey()) {
114	      throw new Error(
115	        'xAI API key is not set. Set the XAI_API_KEY environment variable or add `apiKey` to the provider config.',
116	      );
117	    }
118	
119	    const config = {
120	      ...this.config,
121	      ...context?.prompt?.config,
122	    } as XaiImageOptions;
123	
124	    const model = this.getApiModelName();
125	    const responseFormat = config.response_format || 'url';
126	    const isEdit = Boolean(config.image || config.images?.length || config.mask);
127	    const endpoint = isEdit ? '/images/edits' : '/images/generations';
