108	/**
109	 * Parses a single Server-Sent Events (SSE) chunk into an xAI Responses stream event.
110	 *
111	 * The parser extracts and concatenates `data:` lines, then attempts to parse JSON.
112	 * It intentionally returns `undefined` for:
113	 * - empty payloads,
114	 * - the terminal `[DONE]` marker, and
115	 * - malformed JSON payloads.
116	 *
117	 * Malformed payloads are ignored for stream robustness and logged at debug level
118	 * to aid troubleshooting of intermittent streaming issues.
119	 */
120	function parseSseEvent(chunk: string): XAIResponsesStreamEvent | undefined {
121	  const data = chunk
122	    .split(/\r?\n/)
123	    .filter((line) => line.startsWith('data:'))
124	    .map((line) => line.slice('data:'.length).trimStart())
125	    .join('\n')
126	    .trim();
127	
128	  if (!data || data === '[DONE]') {
129	    return undefined;
130	  }
131	
132	  try {
133	    return JSON.parse(data) as XAIResponsesStreamEvent;
134	  } catch {
135	    logger.debug('[xAI Responses] Ignoring malformed SSE payload', { data });
136	    return undefined;
137	  }
138	}
