140	async function readStreamingResponse(response: Response): Promise<any> {
141	  if (!response.body) {
142	    throw new Error('xAI streaming response has no body');
143	  }
144	
145	  const reader = response.body.getReader();
146	  const decoder = new TextDecoder();
147	  let buffer = '';
148	  let latestResponse: any;
149	  let outputText = '';
150	
151	  const processChunk = (chunk: string) => {
152	    const event = parseSseEvent(chunk);
153	    if (!event) {
154	      return;
155	    }
156	
157	    if (event.response && typeof event.response === 'object') {
158	      latestResponse = event.response;
159	    } else if (Array.isArray(event.output)) {
160	      latestResponse = event;
161	    }
162	
163	    if (typeof event.delta === 'string') {
164	      outputText += event.delta;
165	    } else if (typeof event.output_text?.delta === 'string') {
166	      outputText += event.output_text.delta;
167	    }
168	  };
169	
170	  while (true) {
171	    const { done, value } = await reader.read();
172	    if (done) {
173	      break;
174	    }
175	
176	    buffer += decoder.decode(value, { stream: true });
177	    const chunks = buffer.split(/\r?\n\r?\n/);
178	    buffer = chunks.pop() || '';
179	    for (const chunk of chunks) {
180	      processChunk(chunk);
181	    }
182	  }
183	
184	  buffer += decoder.decode();
185	  if (buffer.trim()) {
186	    processChunk(buffer);
187	  }
188	
189	  if (latestResponse) {
190	    return latestResponse;
191	  }
192	
193	  if (outputText) {
194	    return {
195	      output: [
196	        {
197	          type: 'message',
198	          role: 'assistant',
199	          content: [{ type: 'output_text', text: outputText }],
200	        },
201	      ],
202	    };
203	  }
204	
205	  throw new Error('xAI streaming response did not include output content');
206	}
